# 40_fig_attribution_slopes.R — Figure 2.17: does turbulence moderate the attribution link?
#
# ⭐ RECONSTRUCTED 29 Aug 2026. The original script (`zucco_interaction_cleanPC1.R`, run 27 Aug,
#   per data_workspace_2026-07/_exploratory_ch3-10/attribution_test/ZUCCO_INTERACTION_NOTES.md)
#   was never saved to disk — only its outputs (PNGs, results .txt, a few intermediate CSVs)
#   survived. This rebuilds the analysis from those notes and validates against the recorded
#   per-item coefficients (ZUCCO_INTERACTION_CLEANPC1_RESULTS.txt) before trusting the figure.
#
# ⛔ CIRCULARITY FIX (PJ, 27 Aug: "danger that we included expected MIP in the PCA"): the
#   turbulence index used here is NOT the book's canonical six-component composite — it EXCLUDES
#   `unexpected` (built from worry-minus-predicted-worry residuals — the same construct this
#   test's DV measures; Trade unions/strikes was directly circular, feeding both). Computed here
#   as a proper leave-one-out from the canonical six-component panel (same z-score basis as
#   canonical_leave_one_out.csv's "unexpected" row), NOT a fresh five-component rebuild — a fresh
#   rebuild gives a materially different, unstable PC1 (see build_canonical_composite.R's 29 Aug
#   comment) because it re-z-scores each component against a different common sample.
#
# Method: for each of 13 Ipsos MII domains, standardise worry and its real-world "actual"
# indicator within-item (full-sample SD). Split years into turbulence terciles (Low/Mid/High) on
# the clean five-component PC1. Fit worry_z ~ actual_z separately per item x tercile. Two domains
# (Education, Health/NHS) drop out for insufficient span, leaving 11 panels.

rm(list = ls())
.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../..")) else getwd()
})
setwd(.ROOT)
if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, tidyr, ggplot2, patchwork, ggrepel, sandwich, lmtest)

P  <- .ROOT
WS <- file.path(P, "data_workspace_2026-07")
source(file.path(WS, "figure_house_theme.R"))

# ---- 1. Clean five-component PC1 (leave-one-out "unexpected" from the canonical panel) --------
# Sourcing build_canonical_composite.R is safe/idempotent (writes only to composite_canonical/)
# and guarantees this can never drift from the canonical six-component definition.
source(file.path(WS, "composite_canonical", "build_canonical_composite.R"), local = (ce <- new.env()))
keep <- setdiff(ce$COMPS, "unexpected")
keep_z <- paste0(keep, "_z")
cc <- ce$panel[complete.cases(ce$panel[, keep_z]), ]
clean_pca <- prcomp(cc[, keep_z], center = FALSE, scale. = FALSE)
sgn <- if (mean(clean_pca$rotation[,1]) < 0) -1 else 1
pc1_clean <- data.frame(year = cc$year, PC1_clean = as.numeric(clean_pca$x[,1]) * sgn)
cat(sprintf("Clean five-component PC1: %.1f%% var explained, n=%d\n",
    100*clean_pca$sdev[1]^2/sum(clean_pca$sdev^2), nrow(pc1_clean)))


pc1_clean <- pc1_clean |>
  mutate(tertile = ntile(PC1_clean, 3),
         tertile = factor(tertile, levels = 1:3, labels = c("Low","Mid","High")))

# ---- 2. Item-level worry/actual data, standardised within item ---------------------------------
op <- read.csv(file.path(WS, "ch2_public_opinion", "all_items_expected.csv"), stringsAsFactors = FALSE) |>
  group_by(item) |>
  mutate(worry_z = as.numeric(scale(worry)), actual_z = as.numeric(scale(actual))) |>
  ungroup() |>
  inner_join(pc1_clean, by = "year")

EXCLUDE_ITEMS <- c("Education", "Health / NHS")  # insufficient span, per ZUCCO_INTERACTION_NOTES.md
op <- op |> filter(!item %in% EXCLUDE_ITEMS)

# ---- 3. Validate: pooled and per-item interaction model against the recorded results -----------
# Pooled model: SEs clustered by item (per the appendix's own documented method,
# ch02_attribution_interaction_GENERATED.tex — observations across years within an item are not
# independent). Per-item rows use Newey-West (autocorrelation-robust) SEs for the same reason.
pooled <- lm(worry_z ~ actual_z * PC1_clean, data = op)
cat("\n=== Pooled model, clustered-by-item SEs (validate against ZUCCO_INTERACTION_CLEANPC1_RESULTS.txt) ===\n")
print(coeftest(pooled, vcov = vcovCL(pooled, cluster = op$item)))

per_item <- op |> group_by(item) |>
  group_modify(~{
    m <- lm(worry_z ~ actual_z * PC1_clean, data = .x)
    v <- tryCatch(vcovHC(m, type = "HC1"), error = function(e) vcov(m))
    ct <- coeftest(m, vcov = v)
    data.frame(b_inter = ct["actual_z:PC1_clean", "Estimate"],
               se = ct["actual_z:PC1_clean", "Std. Error"],
               p = ct["actual_z:PC1_clean", "Pr(>|t|)"])
  }) |> ungroup() |> arrange(item)
cat("\n=== Per-item interaction, HC1-robust SEs (validate against the same file) ===\n")
print(per_item, n = Inf)

# ---- 4. Per-item x tertile fitted slopes for the figure -----------------------------------------
items <- sort(unique(op$item))
panel_letters <- letters[seq_along(items)]

make_panel <- function(it, tag) {
  d <- op |> filter(item == it)
  fits <- d |> group_by(tertile) |>
    group_modify(~{
      m <- lm(worry_z ~ actual_z, data = .x)
      rng <- range(.x$actual_z, na.rm = TRUE)
      data.frame(actual_z = rng, worry_z = predict(m, newdata = data.frame(actual_z = rng)))
    })
  end_lab <- fits |> group_by(tertile) |> slice_max(actual_z, n = 1) |> ungroup()
  ggplot(d, aes(actual_z, worry_z)) +
    geom_point(colour = "grey55", size = 1.6, alpha = 0.85) +
    geom_line(data = fits, aes(group = tertile, linetype = tertile, linewidth = tertile), colour = "black") +
    geom_text_repel(data = end_lab, aes(label = tertile, fontface = ifelse(tertile == "High", "bold", "plain")),
                     size = 3, direction = "y", nudge_x = 0.15, segment.size = 0.2, min.segment.length = 0) +
    scale_linetype_manual(values = c(Low = "dotted", Mid = "dashed", High = "solid"), guide = "none") +
    scale_linewidth_manual(values = c(Low = 0.5, Mid = 0.5, High = 0.9), guide = "none") +
    labs(tag = tag, title = it, x = "Actual (z)", y = "Worry (z)") +
    house()
}

panels <- Map(make_panel, items, panel_letters)
fig <- wrap_plots(panels, ncol = 4) +
  plot_annotation(
    title = "Figure 2.17: Attribution slope by turbulence tertile",
    subtitle = "Worry on actual condition, fitted per turbulence tertile (clean five-component PC1, 1979-2025). Bold = high turbulence.",
    theme = theme(plot.title = element_text(face = "bold", size = 16),
                  plot.subtitle = element_text(size = 11)))

ggsave(file.path(WS, "ch2_public_opinion", "fig_2_17_attribution_slopes.png"), fig,
       width = 14, height = 10.5, dpi = 200)
cat(sprintf("\nsaved fig_2_17_attribution_slopes.png, %d panels\n", length(items)))
